"""Plain text absence notices for parents."""

from typing import Iterable, List

from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date

def _format_day(when: date) -> str:
    return f"{when:%B} {when.day}, {when.year}"

def _check_owner(student: Student, marks: List[Mark]):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id} does not "
                f"belong to {student.student_id}"
            )

def _absent_days(student: Student, marks: List[Mark]):
    missed = sorted(set(days_missed(marks)))
    if not missed:
        raise ValueError(
            f"no absences: {student.student_id}"
        )
    return missed

def _compose(student: Student, missed: List[date]) -> str:
    name = f"{student.first_name} {student.last_name}"
    count = len(missed)
    unit = "day" if count == 1 else "days"
    when = ", ".join(map(_format_day, missed))
    return (
        f"{name} missed {count} {unit} of class: {when}."
    )

# ---
def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Notice listing the days a student was absent."""
    marks = list(marks)
    _check_owner(student, marks)
    return _compose(student, _absent_days(student, marks))

