import unittest
from datetime import date

from rosterkit.notices import absence_notice
from rosterkit.models import Mark, Student

PUPIL = Student("1001", "Lovelace", "Ada", "A")

def make_mark(month, when, status, pupil="1001"):
    return Mark(pupil, date(2026, month, when), status)

class AbsenceNoticeTests(unittest.TestCase):
    def test_names_count_and_ordered_dates(self):
        marks = [
            make_mark(9, 5, "absent"),
            make_mark(9, 2, "present"),
            make_mark(9, 1, "absent")
        ]
        self.assertEqual(
            absence_notice(PUPIL, marks),
            "Ada Lovelace missed 2 days of class: "
            "September 1, 2026, September 5, 2026."
        )

    def test_single_day_and_excused_ignored(self):
        marks = [
            make_mark(9, 3, "absent"),
            make_mark(9, 4, "excused")
        ]
        self.assertEqual(
            absence_notice(PUPIL, marks),
            "Ada Lovelace missed 1 day of class: "
            "September 3, 2026."
        )

    def test_foreign_mark_rejected(self):
        marks = [
            make_mark(9, 3, "absent"),
            make_mark(9, 3, "absent", pupil="2002")
        ]
        with self.assertRaises(ValueError):
            absence_notice(PUPIL, marks)

    def test_no_absences_rejected(self):
        marks = [make_mark(9, 3, "late")]
        with self.assertRaises(ValueError):
            absence_notice(PUPIL, marks)
